PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS users (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                email TEXT UNIQUE NOT NULL,
                password_hash TEXT NOT NULL,
                full_name TEXT NOT NULL,
                role TEXT CHECK(role IN ('admin', 'master', 'member')) DEFAULT 'member',
                household_id INTEGER,
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
                updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
            , newsletter_subscribed INTEGER DEFAULT 0, terms_accepted_at TEXT, username TEXT);
CREATE TABLE IF NOT EXISTS households (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                master_user_id INTEGER NOT NULL,
                name TEXT NOT NULL,
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (master_user_id) REFERENCES users(id)
            );
CREATE TABLE IF NOT EXISTS user_profiles (
                user_id INTEGER PRIMARY KEY,
                gender TEXT CHECK(gender IN ('male', 'female', 'other')),
                macros_goal TEXT,
                activity_level TEXT,
                dietary_restrictions TEXT,
                sleep_avg INTEGER,
                stress_level INTEGER,
                preferred_language TEXT DEFAULT 'en',
                preferred_currency TEXT DEFAULT 'USD',
                avatar_url TEXT,
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP, weight REAL DEFAULT 0, height REAL DEFAULT 0, age INTEGER DEFAULT 0, goal TEXT DEFAULT 'maintain', daily_calorie_target INTEGER DEFAULT 2000, protein_target INTEGER DEFAULT 150, carbs_target INTEGER DEFAULT 200, fat_target INTEGER DEFAULT 66, diet_mode TEXT DEFAULT 'normal', neck REAL DEFAULT 0, waist REAL DEFAULT 0, hip REAL DEFAULT 0, facebook TEXT, instagram TEXT, twitter TEXT, theme_preference TEXT DEFAULT 'auto', currency TEXT DEFAULT 'USD', goals TEXT DEFAULT 'maintain', onboarding_completed INTEGER DEFAULT 0,
                FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
            );
CREATE TABLE IF NOT EXISTS recipes (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                image_url TEXT,
                local_image_path TEXT,
                prep_time INTEGER,
                cook_time INTEGER,
                serves INTEGER DEFAULT 4,
                calories INTEGER,
                protein INTEGER,
                carbs INTEGER,
                fat INTEGER,
                is_healthy BOOLEAN DEFAULT 0,
                category TEXT,
                subcategory TEXT,
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE IF NOT EXISTS recipe_translations (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                recipe_id INTEGER NOT NULL,
                language_code TEXT NOT NULL,
                title TEXT NOT NULL,
                description TEXT,
                ingredients_json TEXT,
                method_json TEXT,
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
                UNIQUE(recipe_id, language_code),
                FOREIGN KEY (recipe_id) REFERENCES recipes(id) ON DELETE CASCADE
            );
CREATE TABLE IF NOT EXISTS water_logs (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER NOT NULL,
                date DATE NOT NULL,
                amount_ml INTEGER NOT NULL,
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
            );
CREATE TABLE IF NOT EXISTS fasting_logs (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER NOT NULL,
                start_time DATETIME NOT NULL,
                end_time DATETIME,
                goal_hours INTEGER DEFAULT 16,
                mood_at_end TEXT,
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
            );
CREATE TABLE IF NOT EXISTS weight_logs (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER NOT NULL,
                week_date DATE NOT NULL,
                weight REAL NOT NULL,
                notes TEXT,
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
                UNIQUE(user_id, week_date),
                FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
            );
CREATE TABLE IF NOT EXISTS daily_checkins (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER NOT NULL,
                date DATE NOT NULL,
                sleep_hours REAL,
                mood_score INTEGER,
                energy_level INTEGER,
                soreness_level INTEGER,
                notes TEXT,
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP, sport_type TEXT DEFAULT NULL, training_location TEXT DEFAULT NULL, equipment TEXT DEFAULT '[]', crossfit_level TEXT DEFAULT NULL, gym_workout_type TEXT DEFAULT NULL, muscle_group TEXT DEFAULT NULL,
                UNIQUE(user_id, date),
                FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
            );
CREATE TABLE IF NOT EXISTS daily_logs (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER NOT NULL,
                date DATE NOT NULL,
                food_name TEXT NOT NULL,
                grams REAL,
                meal_type TEXT,
                calories REAL,
                protein REAL,
                carbs REAL,
                fat REAL,
                minerals TEXT,
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
            );
CREATE TABLE IF NOT EXISTS ingredients (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                category TEXT,
                calories REAL,
                protein REAL,
                carbs REAL,
                fat REAL,
                minerals TEXT,
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE IF NOT EXISTS grocery_budgets (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                household_id INTEGER NOT NULL,
                month TEXT NOT NULL,
                initial_budget REAL DEFAULT 3000,
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
                UNIQUE(household_id, month),
                FOREIGN KEY (household_id) REFERENCES households(id) ON DELETE CASCADE
            );
CREATE TABLE IF NOT EXISTS grocery_items (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                budget_id INTEGER NOT NULL,
                name TEXT NOT NULL,
                category TEXT,
                default_unit TEXT,
                estimated_price_per_unit REAL,
                quantity REAL DEFAULT 1,
                is_purchased BOOLEAN DEFAULT 0,
                is_out_of_stock BOOLEAN DEFAULT 0,
                buy_next_month BOOLEAN DEFAULT 0,
                actual_price REAL,
                comment TEXT,
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (budget_id) REFERENCES grocery_budgets(id) ON DELETE CASCADE
            );
CREATE TABLE IF NOT EXISTS forum_posts (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER NOT NULL,
                title TEXT NOT NULL,
                content TEXT NOT NULL,
                category TEXT DEFAULT 'general',
                likes_count INTEGER DEFAULT 0,
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP, image_url TEXT, likes INTEGER DEFAULT 0,
                FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
            );
CREATE TABLE IF NOT EXISTS forum_comments (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                post_id INTEGER NOT NULL,
                user_id INTEGER NOT NULL,
                content TEXT NOT NULL,
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP, image_url TEXT,
                FOREIGN KEY (post_id) REFERENCES forum_posts(id) ON DELETE CASCADE,
                FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
            );
CREATE TABLE IF NOT EXISTS forum_likes (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                post_id INTEGER NOT NULL,
                user_id INTEGER NOT NULL,
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
                UNIQUE(post_id, user_id),
                FOREIGN KEY (post_id) REFERENCES forum_posts(id) ON DELETE CASCADE,
                FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
            );
CREATE TABLE IF NOT EXISTS meal_ratings (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                meal_id INTEGER NOT NULL,
                user_id INTEGER NOT NULL,
                rating INTEGER NOT NULL CHECK(rating >= 1 AND rating <= 5),
                comment TEXT,
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
                UNIQUE(meal_id, user_id),
                FOREIGN KEY (meal_id) REFERENCES recipes(id) ON DELETE CASCADE,
                FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
            );
CREATE TABLE IF NOT EXISTS ai_workout_logs (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id TEXT NOT NULL,
        date TEXT NOT NULL,
        model TEXT,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP
      );
CREATE TABLE IF NOT EXISTS completed_workouts (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id TEXT NOT NULL,
        date TEXT NOT NULL,
        workout_json TEXT NOT NULL,
        feedback_json TEXT,
        notes TEXT,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP
      );
CREATE TABLE IF NOT EXISTS password_resets (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL UNIQUE,
    token_hash TEXT NOT NULL,
    expires_at TEXT NOT NULL,
    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (user_id) REFERENCES users(id)
);
CREATE TABLE IF NOT EXISTS contact_submissions (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, email TEXT NOT NULL, subject TEXT NOT NULL, message TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP, status TEXT DEFAULT 'new');
CREATE TABLE IF NOT EXISTS system_settings (
                    key TEXT PRIMARY KEY,
                    value TEXT
                );
DELETE FROM sqlite_sequence;
CREATE UNIQUE INDEX idx_users_username ON users(username);
COMMIT;
